const int aaSteps = 5;
const float scale1 = 1.2;
const float scale2 = .1;
const float radius = .03;

// quasirandom sequences, kind of like an n-dimensional golden ratio
const vec2 quasi2 = vec2(0.7548777,0.5698403);
const vec3 quasi3 = vec3(0.8191725,0.6710436,0.5497005);

vec3 TransformToNearestDot( in vec3 pos, out ivec3 idx )
{
    // 10x10x10 groups of 10x10x10
    pos += scale1*5.;
    vec3 uvw1 = floor(pos/scale1);
    uvw1 = clamp(uvw1,0.,9.);
    pos -= uvw1*scale1 + scale1/2.;

    pos += scale2*5.;
    vec3 uvw2 = floor(pos/scale2);
    uvw2 = clamp(uvw2,0.,9.);
    pos -= uvw2*scale2 + scale2/2.;

    idx = ivec3(uvw1)*10 + ivec3(uvw2);

    return pos;
}

float SDF( vec3 pos )
{
    ivec3 idx;
    pos = TransformToNearestDot( pos, idx );

    return length(pos)-radius;
}

vec3 Render( vec2 fragCoord )
{
    vec3 ray = vec3( (fragCoord-iResolution.xy*.5)/iResolution.x, .5 );
    vec3 pos = vec3(0,0,-12);

    vec3 angle = vec3(.17,.07,.11)*iTime;

    mat3 rot = mat3(cos(angle.x),0,sin(angle.x), 0,1,0, -sin(angle.x),0,cos(angle.x))
              *mat3(1,0,0, 0,cos(angle.y),sin(angle.y), 0,-sin(angle.y),cos(angle.y))
              *mat3(cos(angle.x),-sin(angle.x),0, sin(angle.x),cos(angle.x),0, 0,0,1);
    ray = ray*rot; pos = pos*rot;

    float t = 0.;
    float minh = 1e10;
    float minht = 0.;
    for ( int i=0; i < 200; i++ )
    {
        float h = SDF(pos+ray*t);
        t += h;
        if ( h < minh ) { minht = t; minh = min(minh,h); }
        if ( h < .0001 || t > 50. ) break;
    }

    //return exp2(-minh/(.015*vec3(.1,1.,1.2)));

    if ( t >= 50. ) return vec3(0); // bg

    pos += minht*ray;

    //return fract(quasi3*dot(quasi3,floor(pos/scale2)));

    ivec3 idx;
    TransformToNearestDot(pos,idx);

    vec3 col = vec3( (idx+ivec3(iTime*60./vec3(3,7,1)))%99 )/99.;
    col *= smoothstep(.005,.001,minh); // make near misses look a little better

    vec2 d = vec2(-1,1)*.001;
    vec3 normal = normalize(
                    SDF(pos+d.xxx)*d.xxx +
                    SDF(pos+d.yyx)*d.yyx +
                    SDF(pos+d.yxy)*d.yxy +
                    SDF(pos+d.xyy)*d.xyy
                );
    col *= step(dot(normal,ray),-.3);

    return col;
}

void mainImage( out vec4 fragColour, in vec2 fragCoord )
{
    fragColour.rgb = vec3(0);
    for ( int i=0; i < aaSteps; i++ )
    {
        fragColour.rgb += Render( fragCoord + fract(quasi2*float(i)) );
    }
    fragColour.rgb /= float(aaSteps);

    fragColour.rgb = pow( fragColour.rgb, vec3(1./2.2) );
    fragColour.a;
}
